#!/usr/bin/env bash
set -euo pipefail
TARGET="app/src/main/java/com/arsany/facebookvideodownloader/MainActivity.kt"
BACKUP="${TARGET}.before_v3"
if [ ! -f "$TARGET" ]; then echo "ERROR: project file not found: $TARGET"; exit 1; fi
cp "$TARGET" "$BACKUP"
python3 - "$TARGET" <<'PYCODE'
import sys, base64
target=sys.argv[1]
data=base64.b64decode("""""")
open(target,"wb").write(data)
print("Applied corrected MainActivity.kt")
PYCODE
echo "Backup created at $BACKUP"
